head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnUseEditFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 useEditFormat 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 useEditFormat 속성을 설정할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "Body Column 이 inputType='calendar' 인 경우에 동작합니다(비-calendar Column 은 설정되지 않습니다).",
        "useEditFormat(필수) 파라미터를 true 로 설정하면 Body Cell 편집 상태에서 입력 포맷이 적용됩니다.",
        "useEditFormat(필수) 파라미터를 false 로 설정하면 Body Cell 편집 상태에서 입력 포맷이 적용되지 않습니다.",
        "useEditFormat=true 로 설정 시 editPlaceholderChar 속성이 설정되어 있으면 displayFormat 속성값이 입력 포맷으로 적용되어야 합니다.",
        "useEditFormat=true 로 설정 시 editPlaceholderChar 속성이 미설정이면 calendarValueType 속성값에 따라 엔진에 정의된 입력 포맷이 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 은 초기 selectedIndex 미적용 -> 기본값 명시 (par_useEditFormat = true(코드값 2))
    par_useEditFormat.setValue("2");
};



// comp 생성 : calendar(editPlaceholderChar 설정)/calendar(editPlaceholderChar 미설정)/text(비-calendar)/calendar(숨김) Column 구성
//  setColumnUseEditFormat 은 inputType='calendar' 인 Column 에서만 동작한다.
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 인덱스 0:calDate1(calendar, editPlaceholderChar 설정) / 1:calDate2(calendar, editPlaceholderChar 미설정) / 2:txtName(text) / 3:calDate3(calendar 숨김)\n[절차] columnInfo·useEditFormat 선택 후 [setColumnUseEditFormat] 실행 -> getColumnUseEditFormat 반영값 출력. calendar 셀 더블클릭 -> 편집 입력값 자동 출력, 이어서 입력을 전체선택 후 삭제하면 마스크 확인.\n[확인] calendar Column 만 반영(text 미반영). useEditFormat=true 면 편집값에 displayFormat 적용(false 는 원본). editPlaceholderChar 설정(idx0) 은 입력을 비우면 마스크 ____/__/__ 표시, 미설정(idx1) 은 마스크 없음(빈값)."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="calDate1" name="calDate1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="calDate2" name="calDate2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtName" name="txtName" dataType="text"></w2:column>';
    strDlt += '<w2:column id="calDate3" name="calDate3" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "calDate1": "20260101", "calDate2": "20260201", "txtName": "노트북", "calDate3": "20260301" },
        { "calDate1": "20260102", "calDate2": "20260202", "txtName": "모니터", "calDate3": "20260302" },
        { "calDate1": "20260103", "calDate2": "20260203", "txtName": "키보드", "calDate3": "20260303" },
        { "calDate1": "20260104", "calDate2": "20260204", "txtName": "마우스", "calDate3": "20260304" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        editable: "true",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody) - Header inputType 은 text, gBody 가 실제 inputType
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:660px;height:240px;" ev:onbeforeedit="scwin.target1_onbeforeedit">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnUseEditFormat 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol1" value="일자1(calendar editPlaceholderChar 설정)"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol2" value="일자2(calendar editPlaceholderChar 미설정)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="품목(text)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="일자3(calendar 숨김)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : calDate1 (calendar, editPlaceholderChar='_' 설정 -> true 시 displayFormat 마스크 적용) 초기 useEditFormat=false
    strTarget += '<w2:column width="170" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" editPlaceholderChar="_" useEditFormat="false" id="calDate1" dataList="calDate1"></w2:column>';
    // index 1 : calDate2 (calendar, editPlaceholderChar 미설정 -> true 시 displayFormat 이 아닌 calendarValueType 기반 엔진 포맷)
    //   displayFormat 을 일부러 'yyyy-MM-dd'(대시) 로 두어, 편집 입력포맷이 displayFormat 이 아니라 calendarValueType(yearMonthDate) 기반 포맷임을 구분 검증
    strTarget += '<w2:column width="170" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy-MM-dd" useEditFormat="false" id="calDate2" dataList="calDate2"></w2:column>';
    // index 2 : txtName (text, 비-calendar) -> setColumnUseEditFormat 미동작
    strTarget += '<w2:column width="140" style="" inputType="text" id="txtName" dataList="txtName"></w2:column>';
    // index 3 : calDate3 (calendar) - setColumnVisible(3,false) 로 숨김 -> 숨김 포함 인덱스 검증용
    strTarget += '<w2:column width="*" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" editPlaceholderChar="_" useEditFormat="false" id="calDate3" dataList="calDate3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 네번째 Column(calDate3, 인덱스 3) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(3, false);
}



// [실행] setColumnUseEditFormat : columnInfo(인덱스) + useEditFormat(true/false) 로 해당 Column 의 useEditFormat 속성을 설정한다.
//  - 설정 직후 쌍이 되는 getColumnUseEditFormat(columnInfo) 로 반영값을 확인한다.
//    (calendar Column 만 반영, 비-calendar / 유효하지 않은 인덱스는 미반영)
scwin.btn_setColumnUseEditFormat_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    // gdl_boolean 바인딩 -> label('true'/'false') 로 분기 (getText)
    let useEditFormat = (par_useEditFormat.getText() === 'true');

    // 설정
    target1.setColumnUseEditFormat(columnInfo, useEditFormat);

    // 쌍이 되는 get 으로 반영값 확인 (set + get)
    let after = target1.getColumnUseEditFormat(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("setColumnUseEditFormat(" + columnInfo + ", " + useEditFormat + ") -> getColumnUseEditFormat: " + after);
}



// [이벤트] calendar 셀을 더블클릭해 편집모드로 진입하면(onbeforeedit), 편집 입력창의 적용 포맷(마스크/placeholder)을 캡처하여 출력한다.
//  - useEditFormat=true + editPlaceholderChar 설정  -> displayFormat 마스크(예 ____/__/__)
//  - useEditFormat=true + editPlaceholderChar 미설정 -> calendarValueType 기반 엔진 포맷
//  - useEditFormat=false -> 편집 입력창에 입력 포맷 미적용
scwin.target1_onbeforeedit = function (row, col, value) {
    let colID = target1.getColumnID(col);
    let use = target1.getColumnUseEditFormat(col);
    // 편집 입력창(inputCalendar) 렌더 직후 값을 읽기 위해 다음 tick 으로 미룸
    //  calendar 편집 입력창은 셀(td) 자식이 아닌 전역 오버레이(input id=G_{gridId}__{colID}_input) 로 렌더됨
    setTimeout(function () {
        let editor = document.querySelector("input[id^='G_'][id$='__" + colID + "_input']");
        if (!editor) { return; }

        wf_body_bottom.getObj("scwin").setReturnValue("편집모드 [" + colID + "] useEditFormat=" + use + " -> 입력값: '" + editor.value + "'");

        // 입력을 전체선택 후 삭제(실제 키 입력)하면 editPlaceholderChar 설정 컬럼은 마스크(____/__/__)가, 미설정 컬럼은 빈값이 표시됨
        //  -> keyup 으로 현재 입력값을 출력하여 마스크를 결과창에서 확인 (addEventListener + 요소당 1회 가드로 중복 방지)
        if (!editor._maskLoggerAttached) {
            editor._maskLoggerAttached = true;
            editor._lastLogged = editor.value;
            editor.addEventListener('keyup', function () {
                if (editor.value !== editor._lastLogged) {
                    editor._lastLogged = editor.value;
                    wf_body_bottom.getObj("scwin").setReturnValue("입력값: '" + editor.value + "'");
                }
            });
        }
    }, 100);
};
